{
  "passageId": "personal-identity",
  "items": [
    {
      "id": "R1",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "과거와 현재의 인격이 동일하다는 사실을 근거로 약속을 지켜야 한다는 당위 판단을 도출한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "약속 이행에 관한 판단은 인격의 동일성이 생각의 기반이라는 일반적 설명의 구체적 사례이다."
    },
    {
      "id": "R3",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "칸트는 자기의식만으로 영혼의 실재를 보장할 수 없다고 하여 기존의 영혼 중심 설명에 문제를 제기한다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자기의식이 인식의 조건에 불과하다는 규정을 근거로 영혼의 실재가 보장되지 않는다는 결론을 도출한다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "인식의 조건은 실재를 보장하지 않는다는 일반 원리를 자기의식과 영혼의 경우에 적용한다."
    },
    {
      "id": "R6",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 자기의식이 영혼의 실재 가능성은 열어두지만 실재 보장까지 하지는 못한다는 한계를 제시한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "칸트의 이론 내부에서 자기의식이 영혼의 실재를 보장하지 않는다는 설명이 영혼과 인격의 동일시를 반박하는 근거가 된다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 전제의 의식이 대상의 실재를 함축하는지라는 같은 기준에서 서로 다른 값을 가진다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 전제에서 의식의 의미가 다르다는 점을 근거로 영혼이 인격이라는 결론의 도출을 부정한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 번째 전제가 생각하는 나는 생각한다는 말과 같다는 분석이 그 의식은 실재를 함축하지 않는다는 판단을 뒷받침한다."
    },
    {
      "id": "R11",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "영혼에서 인격의 동일성을 도출하는 추론의 한계에 대응하여 동일한 인격으로 인식된다는 선행 가정을 대안으로 제시한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "경험적·윤리적 판단의 가능성에 필요하다는 이유로 동일 인격의 가정이 선행되어야 한다는 주장을 뒷받침한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생각의 구성이 시간을 따른다는 성질에서 통시적으로 동일한 인격이 필요하다는 판단을 이끌어 낸다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "생각의 시간적 구성과 동일 인격의 필요성에 관한 설명이 판단을 가능하게 하는 선행 가정의 의미를 더 자세히 풀어 준다."
    },
    {
      "id": "R15",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "스트로슨이라는 한 인물 안에서 칸트의 일부 견해에는 동의하면서 다른 가정은 비판하는 수용의 한계가 나타난다."
    },
    {
      "id": "R16",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "스트로슨이 칸트의 동일 인격 가정을 철학적 상상에 불과하다고 명시적으로 문제 삼는다."
    },
    {
      "id": "R17",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인격을 설명할 때 신체를 포함하는지를 두고 칸트와 스트로슨의 관점을 나란히 대비한다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "신체를 매개로 대상을 경험한다는 사실이 경험으로 인격의 통시적 동일성을 설명하는 주장의 근거가 된다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자아 인식이 경험적 인식에서 추상화된다는 설명으로부터 경험이 인격의 동일성을 뒷받침한다는 결론을 도출한다."
    },
    {
      "id": "R20",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "자아 인식이 경험에 의존한다는 설명을 자기의식에도 마찬가지로 적용한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "스트로슨의 논증 내부에서 자기의식의 경험 의존성이 칸트의 견해가 잘못이라는 판단의 근거가 된다."
    },
    {
      "id": "R22",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "스트로슨이 자기의식을 인식의 조건으로 규정한 칸트의 주장을 명시적으로 부정한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "동일한 자아가 경험적 인식의 필요조건이라는 점에서 자아 인식은 경험의 추상화 결과가 아니라는 결론을 이끌어 낸다."
    },
    {
      "id": "R24",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "롱게네스는 자아 인식이 경험에서 추상화된다는 스트로슨의 주장을 부정하고 그 반대의 근거를 제시한다."
    },
    {
      "id": "R25",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "자아를 경험의 성립 조건으로 보는 관점과 자기의식을 경험에 의존시키는 관점을 대비한다."
    },
    {
      "id": "R26",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "롱게네스는 자아 인식의 경험적 기원은 부정하면서도 자아와 인격의 적용 범위는 경험하는 인간으로 한정한다."
    },
    {
      "id": "R27",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "인간이 지닌 자율성의 뜻을 시공간적 경험 속에서 스스로 선택하는 것으로 풀어 설명한다."
    },
    {
      "id": "R28",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율성을 경험 속 자기 선택으로 규정한 데서 그러한 선택에는 신체가 필요하다는 판단을 도출한다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율성이 시공간적 경험 속 선택이라는 뜻에 근거하여 선택의 주체가 살아 있어야 한다는 필요성을 이끌어 낸다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인간의 자율성을 경험 속 자기 선택으로 이해하는 설명이 살아 있는 신체의 필요성과 신체 중심의 동일성 기준을 뒷받침한다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자율적 선택에 신체가 필요하다는 점을 근거로 통시적으로 자신의 것으로 인식하는 신체를 동일성의 기준으로 제시한다."
    },
    {
      "id": "R32",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "경험 속 자기 선택에는 살아 있음이 필요하다는 점이 신체를 인격 동일성의 기준으로 삼는 주장을 뒷받침한다."
    },
    {
      "id": "R33",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "스트로슨과 롱게네스는 인격 문제를 설명할 때 신체를 중요하게 고려한다는 공통된 관점을 보인다."
    },
    {
      "id": "R34",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "칸트의 선행 가정과 생각의 시간적 구성에 관한 설명이 인격의 동일성은 모든 생각의 기반이라는 진술을 구체화한다."
    }
  ]
}

